import re

def decode_json_string(token):
    text = token[1:-1]
    result = ""
    index = 0
    escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
    while index < len(text):
        if text[index] != '\\':
            result += text[index]
            index += 1
        else:
            index += 1
            char = text[index]
            if char == 'u':
                result += chr(int(text[index + 1:index + 5], 16))
                index += 5
            else:
                result += escapes[char]
                index += 1
    return result

def get_lines(value):
    if isinstance(value, list):
        return value
    tokens = re.findall(r'"(?:\\.|[^"\\])*"|[{}\[\],:]|[^\s{}\[\],:]+', value)
    fields = {'amount': [], 'description': []}
    for index in range(len(tokens) - 2):
        token = tokens[index]
        if token.startswith('"') and tokens[index + 1] == ':' and token[1:-1] in fields:
            next_token = tokens[index + 2]
            fields[token[1:-1]].append(decode_json_string(next_token) if next_token.startswith('"') else next_token)
    return [{'amount': amount, 'description': description} for amount, description in zip(fields['amount'], fields['description'])]

def format_cents(value):
    whole, fraction = divmod(abs(value), 100)
    sign = '-' if value < 0 else ''
    return sign + str(whole) + '.' + str(fraction).zfill(2)

