import re

def parse_json(text):
    pattern = re.compile(r'\s*(?:"(?:\\.|[^"\\])*"|[{}\[\]:,]|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null)')
    tokens = [match.group(0).strip() for match in pattern.finditer(text)]
    position = [0]

    def decode_string(token):
        value = token[1:-1]
        result = []
        index = 0
        escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
        while index < len(value):
            char = value[index]
            if char != '\\':
                result.append(char)
                index += 1
            else:
                code = value[index + 1]
                if code == 'u':
                    result.append(chr(int(value[index + 2:index + 6], 16)))
                    index += 6
                else:
                    result.append(escapes[code])
                    index += 2
        return ''.join(result)

    def parse_value():
        token = tokens[position[0]]
        position[0] += 1
        if token == '[':
            values = []
            if tokens[position[0]] == ']':
                position[0] += 1
                return values
            while True:
                values.append(parse_value())
                separator = tokens[position[0]]
                position[0] += 1
                if separator == ']':
                    return values
        if token == '{':
            result = {}
            if tokens[position[0]] == '}':
                position[0] += 1
                return result
            while True:
                key = decode_string(tokens[position[0]])
                position[0] += 2
                result[key] = parse_value()
                separator = tokens[position[0]]
                position[0] += 1
                if separator == '}':
                    return result
        if token.startswith('"'):
            return decode_string(token)
        if token == 'true':
            return True
        if token == 'false':
            return False
        if token == 'null':
            return None
        return float(token) if '.' in token or 'e' in token.lower() else int(token)

    return parse_value()

